# Replays traces of the Python token-cap simulation (elixir/token_cap_golden.json,
# generated by scripts/gen_elixir_token_cap_golden.py) through TokenCap and
# PacingController together.
# Run: make -C elixir test
ExUnit.start()

defmodule TokenCapTest do
  use ExUnit.Case, async: true

  alias TokenCap.{Grants, Reports}

  @golden Path.join(__DIR__, "token_cap_golden.json") |> File.read!() |> JSON.decode!()
  @p_tol 1.0e-8

  defp kw(map), do: Enum.map(map, fn {k, v} -> {String.to_existing_atom(k), v} end)

  # the controller, or nil for the full-throttle cases (p = 1 always)
  defp controller(nil), do: nil
  defp controller(opts), do: PacingController.new(kw(opts))

  defp decide(nil, _spend), do: {1.0, nil}

  defp decide(ctl, spend) do
    {p, _send?, ctl} = PacingController.step(ctl, spend)
    {p, ctl}
  end

  for %{"name" => name} = golden <- @golden["cases"] do
    @golden_case golden

    test "replays the Python simulation: #{name}" do
      g = @golden_case
      ctl = controller(g["controller"])

      cap =
        case g["mode"] do
          "reports" -> Reports.new(kw(g["cap"]))
          "grants" -> Grants.new(kw(g["cap"]))
        end

      Enum.reduce(Enum.with_index(g["steps"]), {ctl, cap}, fn {s, i}, {ctl, cap} ->
        {p, ctl} = decide(ctl, s["observed_spend"])

        assert abs(p - s["p"]) <= @p_tol * max(1.0, s["p"]),
               "period #{i}: p = #{p}, Python #{s["p"]}"

        wanted = s["wanted"]

        case cap do
          %Reports{} ->
            a = Reports.allowance(cap)
            assert a == s["allowance"], "period #{i}: allowance #{a}, Python #{s["allowance"]}"
            tokens = min(wanted, a)
            assert tokens == s["tokens"]

            ctl =
              ctl &&
                PacingController.correct_exposure(ctl, Reports.effective_p(p, tokens, wanted))

            cap =
              cap
              |> Reports.record_use(tokens)
              |> Reports.record_failures(s["failures_reported"])

            assert cap.used <= cap.budget_tokens + cap.failures_reported
            {ctl, cap}

          %Grants{} ->
            assert Grants.allowance(cap, s["observed_spend"]) == s["allowance"]
            {grant, cap} = Grants.grant(cap, s["observed_spend"])
            assert grant == s["grant"], "period #{i}: grant #{grant}, Python #{s["grant"]}"
            assert min(wanted, grant) == s["tokens"]
            {ctl, cap}
        end
      end)

      assert g["final_spend"] <= g["cap"]["budget"]
    end
  end

  # ------------------------------------------------------------------ unit tests

  test "(a) allowance: budget plus reported failures minus used, never negative" do
    cap = Reports.new(budget: 10)
    assert Reports.allowance(cap) == 10
    cap = Reports.record_use(cap, 10)
    assert Reports.allowance(cap) == 0
    cap = Reports.record_failures(cap, 3)
    assert Reports.allowance(cap) == 3
  end

  test "(a) the budget pays for floor(B / c) tokens" do
    assert Reports.allowance(Reports.new(budget: 10, unit_cost: 3)) == 3
    assert Reports.allowance(Reports.new(budget: 0.9, unit_cost: 0.3)) == 3
  end

  test "(a) effective p scales p by the share of bids that got a token" do
    assert Reports.effective_p(0.02, 3, 4) == 0.015
    assert Reports.effective_p(0.02, 0, 0) == 0.02
  end

  test "(b) grants half the allowance and counts its grants until they land" do
    cap = Grants.new(budget: 100, delay: 10, step: 5, share: 0.5)
    {g1, cap} = Grants.grant(cap, 0)
    {g2, cap} = Grants.grant(cap, 0)
    {g3, cap} = Grants.grant(cap, 0)
    {g4, cap} = Grants.grant(cap, 0)
    # d = 10 s = 2 periods, so the grants of the last 2 periods are unresolved:
    # 50 of 100; 25 of 100 - 50; 13 of 100 - 50 - 25; then the 50 has landed
    # (its spend, 0 here, is visible): 31 of 100 - 25 - 13 = 62
    assert {g1, g2, g3, g4} == {50, 25, 13, 31}
    # now unresolved: 13 and 31; the budget shows 20 of spend
    assert Grants.allowance(cap, 20) == 100 - 20 - 13 - 31
  end

  test "(b) headroom rule grants h times the expected bids, capped by the allowance" do
    cap = Grants.new(budget: 100, delay: 30, step: 5, headroom: 1.5)
    assert {15, _} = Grants.grant(cap, 0, expected_bids: 10.0)
    assert {100, _} = Grants.grant(cap, 0, expected_bids: 1000.0)
  end

  test "(b) needs exactly one grant rule" do
    assert_raise ArgumentError, fn -> Grants.new(budget: 1, delay: 1, step: 1) end

    assert_raise ArgumentError, fn ->
      Grants.new(budget: 1, delay: 1, step: 1, share: 0.5, headroom: 1)
    end
  end
end
